ALTER TABLE customer_memberships ADD COLUMN IF NOT EXISTS frozen_until DATE;
ALTER TABLE customer_memberships ADD COLUMN IF NOT EXISTS family_plan BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE membership_lifecycle_events(id UUID PRIMARY KEY,membership_id UUID NOT NULL REFERENCES customer_memberships(id),action VARCHAR(40) NOT NULL,details VARCHAR(1000),actor_user_id UUID REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE membership_entitlement_ledger(id UUID PRIMARY KEY,membership_id UUID NOT NULL REFERENCES customer_memberships(id),entitlement VARCHAR(80) NOT NULL,quantity INT NOT NULL,reference VARCHAR(120),created_at TIMESTAMPTZ NOT NULL DEFAULT now());

CREATE TABLE training_lifecycle_events(id UUID PRIMARY KEY,enrollment_id UUID NOT NULL REFERENCES training_enrollments(id),action VARCHAR(40) NOT NULL,details VARCHAR(1500),actor_user_id UUID REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE training_waitlist(id UUID PRIMARY KEY,batch_id UUID NOT NULL REFERENCES training_batches(id),user_id UUID NOT NULL REFERENCES users(id),participant_name VARCHAR(160) NOT NULL,position INT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(batch_id,user_id));
CREATE TABLE training_progress_notes(id UUID PRIMARY KEY,enrollment_id UUID NOT NULL REFERENCES training_enrollments(id),coach_user_id UUID NOT NULL REFERENCES users(id),note VARCHAR(2000) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE training_certificates(id UUID PRIMARY KEY,enrollment_id UUID NOT NULL UNIQUE REFERENCES training_enrollments(id),certificate_number VARCHAR(40) NOT NULL UNIQUE,issued_at TIMESTAMPTZ NOT NULL DEFAULT now());

CREATE TABLE tournament_result_history(id UUID PRIMARY KEY,tournament_id UUID NOT NULL REFERENCES tournaments(id),fixture_id UUID,old_result VARCHAR(1000),new_result VARCHAR(1000) NOT NULL,reason VARCHAR(1000),submitted_by UUID REFERENCES users(id),approved_by UUID REFERENCES users(id),status VARCHAR(30) NOT NULL DEFAULT 'PENDING',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),approved_at TIMESTAMPTZ);
CREATE TABLE tournament_officials(id UUID PRIMARY KEY,tournament_id UUID NOT NULL REFERENCES tournaments(id),user_id UUID REFERENCES users(id),official_name VARCHAR(160) NOT NULL,role VARCHAR(60) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE tournament_financial_closure(id UUID PRIMARY KEY,tournament_id UUID NOT NULL UNIQUE REFERENCES tournaments(id),income_paise BIGINT NOT NULL DEFAULT 0,expense_paise BIGINT NOT NULL DEFAULT 0,notes VARCHAR(2000),closed_by UUID REFERENCES users(id),closed_at TIMESTAMPTZ NOT NULL DEFAULT now());

CREATE TABLE notification_delivery_attempts(id UUID PRIMARY KEY,notification_id UUID REFERENCES notifications(id),channel VARCHAR(30) NOT NULL,provider VARCHAR(60),destination VARCHAR(200),status VARCHAR(30) NOT NULL,provider_reference VARCHAR(200),error_message VARCHAR(1000),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reminder_schedule(id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id),category VARCHAR(50) NOT NULL,reference_type VARCHAR(50) NOT NULL,reference_id UUID,scheduled_at TIMESTAMPTZ NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'PENDING',created_at TIMESTAMPTZ NOT NULL DEFAULT now());

CREATE TABLE account_data_requests(id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id),request_type VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'REQUESTED',notes VARCHAR(1000),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ);
CREATE TABLE account_merge_requests(id UUID PRIMARY KEY,source_user_id UUID NOT NULL REFERENCES users(id),target_user_id UUID NOT NULL REFERENCES users(id),verified_mobile BOOLEAN NOT NULL DEFAULT FALSE,status VARCHAR(30) NOT NULL DEFAULT 'PENDING',requested_by UUID NOT NULL REFERENCES users(id),approved_by UUID REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ);
CREATE TABLE privileged_mfa(id UUID PRIMARY KEY,user_id UUID NOT NULL UNIQUE REFERENCES users(id),enabled BOOLEAN NOT NULL DEFAULT FALSE,method VARCHAR(30) NOT NULL DEFAULT 'EMAIL_OTP',secret_hash VARCHAR(255),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());

CREATE TABLE facility_emergency_actions(id UUID PRIMARY KEY,facility_id UUID NOT NULL REFERENCES facilities(id),closure_date DATE NOT NULL,reason VARCHAR(1000) NOT NULL,action VARCHAR(30) NOT NULL,affected_bookings INT NOT NULL DEFAULT 0,created_by UUID REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
